import type { SessionInfo } from '@motivation/shared';
import { API_URL } from '../config.js';
import { createJsonClient } from './http.js';

const api = createJsonClient(`${API_URL}/api`);

type Listener = (required: boolean) => void;

/**
 * Story 461: the session lives in an HttpOnly cookie the app cannot read. The app posts a pasted token
 * once (never stored, never synced) and keeps one fact: whether the server has asked for a new one.
 */
export class SessionService {
    private required = false;
    private readonly listeners = new Set<Listener>();

    async signIn(token: string): Promise<SessionInfo> {
        const info = await api.post<SessionInfo>('/session', { token: token.trim() });
        this.set(false);
        return info;
    }

    /** The service worker saw a 401. */
    markRequired(): void {
        this.set(true);
    }

    isRequired(): boolean {
        return this.required;
    }

    /** Called on every change; returns the unsubscribe. */
    subscribe(listener: Listener): () => void {
        this.listeners.add(listener);
        return () => this.listeners.delete(listener);
    }

    private set(required: boolean): void {
        if (this.required === required) return;
        this.required = required;
        for (const listener of this.listeners) listener(required);
    }
}

export const sessionService = new SessionService();
